def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    import re

    token_pattern = re.compile(
        r"SUM|MIN|MAX|IF|[A-Z][1-9][0-9]?|[0-9]+|<>|<=|>=|[+\-*/(),:=<>]"
    )
    precedence = {
        "=": 0, "<>": 0, "<": 0, "<=": 0, ">": 0, ">=": 0,
        "+": 1, "-": 1, "*": 2, "/": 2, "neg": 3,
    }

    def parse(formula):
        tokens = token_pattern.findall(formula)
        # Each frame holds values, operators, function name, and completed arguments.
        frames = [([], [], None, [])]
        expecting_operand = True
        i = 0

        def reduce_one(frame):
            values, operators, _, _ = frame
            op = operators.pop()
            if op == "neg":
                values.append(("neg", values.pop()))
            else:
                right = values.pop()
                left = values.pop()
                values.append((op, left, right))

        def finish_expression(frame):
            while frame[1]:
                reduce_one(frame)
            return frame[0].pop()

        while i < len(tokens):
            token = tokens[i]
            frame = frames[-1]

            if token in ("SUM", "MIN", "MAX", "IF"):
                frames.append(([], [], token, []))
                i += 2  # Skip the function name and opening parenthesis.
                expecting_operand = True
                continue

            if token == "(":
                frames.append(([], [], None, []))
                expecting_operand = True
            elif token == ",":
                frame[3].append(finish_expression(frame))
                expecting_operand = True
            elif token == ")":
                value = finish_expression(frame)
                frames.pop()
                if frame[2] is not None:
                    frame[3].append(value)
                    value = (frame[2], frame[3])
                frames[-1][0].append(value)
                expecting_operand = False
            elif token[0].isdigit():
                frame[0].append(int(token))
                expecting_operand = False
            elif token[0].isalpha():
                if i + 2 < len(tokens) and tokens[i + 1] == ":":
                    frame[0].append(("range", token, tokens[i + 2]))
                    i += 2
                else:
                    frame[0].append(("ref", token))
                expecting_operand = False
            else:
                op = "neg" if token == "-" and expecting_operand else token
                while frame[1] and (
                    precedence[frame[1][-1]] > precedence[op]
                    or (
                        precedence[frame[1][-1]] == precedence[op]
                        and op != "neg"
                    )
                ):
                    reduce_one(frame)
                frame[1].append(op)
                expecting_operand = True
            i += 1

        return finish_expression(frames[0])

    values = {}
    in_progress = set()

    def is_error(value):
        return isinstance(value, str)

    def evaluate(start):
        results = []
        tasks = [("cell", start)]

        while tasks:
            task = tasks.pop()
            kind = task[0]

            if kind == "cell":
                name = task[1]
                if name in values:
                    results.append(values[name])
                elif name not in cells:
                    results.append(0)
                elif name in in_progress:
                    results.append("#CYCLE!")
                else:
                    in_progress.add(name)
                    content = cells[name]
                    if content.startswith("="):
                        expression = parse(content[1:])
                    else:
                        expression = int(content)
                    tasks.append(("finish_cell", name))
                    tasks.append(("eval", expression))

            elif kind == "finish_cell":
                name = task[1]
                values[name] = results[-1]
                in_progress.remove(name)

            elif kind == "eval":
                node = task[1]
                if isinstance(node, int):
                    results.append(node)
                    continue

                op = node[0]
                if op == "ref":
                    tasks.append(("cell", node[1]))
                elif op == "neg":
                    tasks.append(("neg",))
                    tasks.append(("eval", node[1]))
                elif op == "IF":
                    tasks.append(("if", node[1][1], node[1][2]))
                    tasks.append(("eval", node[1][0]))
                elif op in ("SUM", "MIN", "MAX"):
                    arguments = []
                    for arg in node[1]:
                        if isinstance(arg, tuple) and arg[0] == "range":
                            first, last = arg[1], arg[2]
                            col1, col2 = sorted((ord(first[0]), ord(last[0])))
                            row1, row2 = sorted((int(first[1:]), int(last[1:])))
                            for row in range(row1, row2 + 1):
                                for col in range(col1, col2 + 1):
                                    name = chr(col) + str(row)
                                    if name in cells:
                                        arguments.append(("ref", name))
                        else:
                            arguments.append(arg)
                    tasks.append(("aggregate", op, arguments, 0, None))
                else:
                    tasks.append(("left", op, node[2]))
                    tasks.append(("eval", node[1]))

            elif kind == "neg":
                value = results.pop()
                results.append(value if is_error(value) else -value)

            elif kind == "left":
                left = results.pop()
                if is_error(left):
                    results.append(left)
                else:
                    tasks.append(("right", task[1], left))
                    tasks.append(("eval", task[2]))

            elif kind == "right":
                op, left = task[1], task[2]
                right = results.pop()
                if is_error(right):
                    results.append(right)
                elif op == "+":
                    results.append(left + right)
                elif op == "-":
                    results.append(left - right)
                elif op == "*":
                    results.append(left * right)
                elif op == "/":
                    if right == 0:
                        results.append("#DIV/0!")
                    else:
                        quotient = abs(left) // abs(right)
                        results.append(-quotient if (left < 0) != (right < 0) else quotient)
                elif op == "=":
                    results.append(int(left == right))
                elif op == "<>":
                    results.append(int(left != right))
                elif op == "<":
                    results.append(int(left < right))
                elif op == "<=":
                    results.append(int(left <= right))
                elif op == ">":
                    results.append(int(left > right))
                else:
                    results.append(int(left >= right))

            elif kind == "if":
                condition = results.pop()
                if is_error(condition):
                    results.append(condition)
                else:
                    tasks.append(("eval", task[1] if condition else task[2]))

            elif kind == "aggregate":
                op, arguments, index, accumulator = task[1:]
                if index == len(arguments):
                    results.append(0 if accumulator is None else accumulator)
                else:
                    tasks.append(("aggregate_value", op, arguments, index, accumulator))
                    tasks.append(("eval", arguments[index]))

            else:  # aggregate_value
                op, arguments, index, accumulator = task[1:]
                value = results.pop()
                if is_error(value):
                    results.append(value)
                else:
                    if accumulator is None:
                        accumulator = value
                    elif op == "SUM":
                        accumulator += value
                    elif op == "MIN":
                        accumulator = min(accumulator, value)
                    else:
                        accumulator = max(accumulator, value)
                    tasks.append(("aggregate", op, arguments, index + 1, accumulator))

        return results.pop()

    for name in cells:
        if name not in values:
            evaluate(name)

    return {name: values[name] for name in cells}
